import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"Plugins","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/plugins.md","filePath":"user-guide/settings/plugins.md","lastUpdated":1787475408000}'),i={name:"user-guide/settings/plugins.md"};function s(r,e,l,d,g,p){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h1><p>Lists every installed plugin, with the currently-loaded Plugin SDK version shown as a badge in the page header — click it to open the <a href="./../../dev-guide/">Developer Manual</a>, which is what that version number is for.</p><p>The page is split into two panes: the installed plugins on the left, the selected one&#39;s details on the right. They scroll independently, so a long plugin list and a long settings form don&#39;t drag each other around.</p><p>If no plugins are installed, the page shows an empty-state message instead.</p><h2 id="plugin-list" tabindex="-1">Plugin list <a class="header-anchor" href="#plugin-list" aria-label="Permalink to &quot;Plugin list&quot;">​</a></h2><p>One row per installed plugin, showing its name with its version underneath. Selecting a row opens that plugin in the pane on the right.</p><p>The list leads with what there is to do: plugins with their own settings first, then plugins with components you can switch off, then the rest, alphabetical within each group.</p><h2 id="selected-plugin" tabindex="-1">Selected plugin <a class="header-anchor" href="#selected-plugin" aria-label="Permalink to &quot;Selected plugin&quot;">​</a></h2><p>The pane opens on the plugin&#39;s icon, name, and <strong>overall function description</strong>.</p><p>Below that, a plugin that exposes its own configuration (custom settings beyond simple enable/disable) gets two tabs, <strong>Details</strong> and <strong>Configure</strong>. A plugin with nothing to configure has no tab strip at all — its details are the whole pane.</p><h3 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h3><p>The components this plugin registers, grouped by type (search providers, dynamic menu providers, etc.). Each toggleable component has its own <strong>enable/disable checkbox</strong>; a component marked as required shows a lock icon instead and can&#39;t be turned off. Hovering the <strong>(!)</strong> beside a component reveals its detailed function description.</p><p>When a group (or the plugin as a whole) has more than one toggleable component, a <strong>Select All / Deselect All</strong> link appears next to its header, letting you flip every checkbox in that scope at once instead of one at a time.</p><h3 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;Configure&quot;">​</a></h3><p>The plugin&#39;s own settings, edited right here rather than in a separate dialog. A plugin that sorts its settings into two or more groups gets its own row of tabs, one per group.</p><p>Nothing is written until you press <strong>OK</strong>. Leaving this tab — switching back to Details, or picking a different plugin — rolls the fields back to their saved values, so edits you walked away from can&#39;t be committed later by accident.</p><p>For a concrete example of what a plugin&#39;s configuration looks like in practice (e.g. changing a trigger keyword), see <a href="./../instant-answers.html">Instant Answers &amp; Keyword Shortcuts</a>.</p><h2 id="flow-launcher-plugin-support" tabindex="-1">Flow Launcher Plugin Support <a class="header-anchor" href="#flow-launcher-plugin-support" aria-label="Permalink to &quot;Flow Launcher Plugin Support&quot;">​</a></h2><p>In addition to native C# plugins built with <code>Lertaro.PluginSdk</code>, Lertaro includes built-in compatibility with the extensive Flow Launcher plugin ecosystem via the Flow Launcher Bridge.</p><ul><li><strong>Supported Plugin Types</strong>: Flow Launcher plugins written in <strong>C# (.NET)</strong>, <strong>Python 3.12</strong> (with automated background <code>pip</code> dependency resolution from <code>requirements.txt</code>), <strong>Node.js v20 LTS</strong> (with automated background <code>npm</code> dependency resolution from <code>package.json</code>), or standalone <strong>Executables</strong> (<code>.exe</code>).</li><li><strong>Installation</strong>: Drop third-party Flow Launcher plugin folders into <code>&lt;User Data Directory&gt;\\FlowData\\Plugins\\</code>. Lertaro automatically discovers, initializes, and integrates their query triggers and action keywords.</li><li><strong>Isolated Runtimes</strong>: Python (<code>FlowData\\PythonEmbeded-{arch}</code>) and Node.js (<code>FlowData\\NodeEmbeded-{arch}</code>) runtimes are completely self-contained within Lertaro&#39;s user data directory, downloaded on-demand and provisioned without polluting or modifying your system PATH.</li><li><strong>Plugin Management &amp; Configuration</strong>: Type the <code>flow</code> keyword into the search bar to list all loaded Flow Launcher plugins along with their action keywords and status. Selecting any configurable plugin and pressing <strong>Enter</strong> opens its dedicated settings window, with full confirm-to-save and cancel-to-rollback protections.</li></ul>',20)])])}const u=t(i,[["render",s]]);export{c as __pageData,u as default};
